42	        grid.addColumn(Customer::lastName).setHeader("Last name")
43	                .setKey("lastName").setSortProperty("lastName");
44	        grid.addColumn(Customer::email).setHeader("Email")
45	                .setKey("email").setSortProperty("email");
46	        grid.addColumn(Customer::country).setHeader("Country")
47	                .setKey("country").setSortProperty("country");
48	        grid.addColumn(customer -> customer.status().name()).setHeader("Status")
49	                .setKey("status").setSortProperty("status");
50	        grid.setSizeFull();
51	
52	        grid.setItems(
53	                query -> customerService
54	                        .list(query.getOffset(), query.getLimit(), toSorts(query.getSortOrders()))
