import java.text.Normalizer;
import java.util.Arrays;
import java.util.Locale;
import java.util.Set;

/**
 * A filter over the customer list.
 *
 * <p>A customer matches when every whitespace-separated term in {@code name} is
 * a substring of the first or last name — case- and accent-insensitively — and
 * when {@code statuses} is empty or contains the customer's status.
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());

    public CustomerFilter {
        name = name == null ? "" : name;
        statuses = statuses == null ? Set.of() : Set.copyOf(statuses);
    }

    public boolean matches(Customer customer) {
        return matchesStatus(customer) && matchesName(customer);
    }

    private boolean matchesStatus(Customer customer) {
        return statuses.isEmpty() || statuses.contains(customer.status());
    }

    private boolean matchesName(Customer customer) {
        String trimmed = name.trim();
        if (trimmed.isEmpty()) {
            return true;
        }
        String first = fold(customer.firstName());
        String last = fold(customer.lastName());
        return Arrays.stream(trimmed.split("\\s+"))
                .map(CustomerFilter::fold)
                .allMatch(term -> first.contains(term) || last.contains(term));
    }

    private static String fold(String value) {
        return Normalizer.normalize(value, Normalizer.Form.NFD)
                .replaceAll("\\p{M}", "")
                .toLowerCase(Locale.ROOT);
    }
}
